#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/generate/generate-pr-standards-block.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * generate-pr-standards-block.mjs
 *
 * @version 1
 *
 * Emits the mandatory `## Standards compliance` PR-body block: the literal
 * "100% standards met" line plus every standard registered in INDEX.yaml at
 * 100%. Refuses without a fresh green receipt (written only by verify-all on
 * all-green), so the block cannot be generated for a non-green tree.
 *
 * Usage: node generate-pr-standards-block.mjs   (from the web root, after pnpm verify)
 * Exit: 0 (block on stdout), 1 refused.
 */
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import process from "node:process";
import { spawnSync } from "node:child_process";

const MAX_AGE_MS = 10 * 60 * 1000;

function findIndexYaml() {
  const candidates = [
    path.resolve(new URL(".", import.meta.url).pathname, "..", "..", "INDEX.yaml"), // vendored/standards-relative
    path.join(process.cwd(), ".claude", "standards", "INDEX.yaml"),
    path.join(os.homedir(), ".claude", "standards", "INDEX.yaml"),
  ];
  return candidates.find((p) => fs.existsSync(p));
}

const idxPath = findIndexYaml();
if (!idxPath) { process.stderr.write("❌ generate-pr-standards-block: INDEX.yaml not found\n"); process.exit(1); }
const py = spawnSync("python3", ["-c", "import yaml,json,sys;d=yaml.safe_load(open(sys.argv[1]));print(json.dumps(sorted((d.get('standards') or {}).keys())))", idxPath], { encoding: "utf8" });
if (py.status !== 0) { process.stderr.write(`❌ generate-pr-standards-block: cannot parse INDEX.yaml — ${py.stderr}`); process.exit(1); }
const standards = JSON.parse(py.stdout);

const gitDir = spawnSync("git", ["rev-parse", "--git-dir"], { encoding: "utf8" }).stdout?.trim();
let receipt = null;
try { receipt = JSON.parse(fs.readFileSync((path.isAbsolute(gitDir) ? path.join(gitDir, "verify-receipt.json") : path.join(process.cwd(), gitDir, "verify-receipt.json")), "utf8")); } catch { /* missing */ }
const age = receipt ? Date.now() - Date.parse(receipt.ts) : Infinity;
if (!receipt || !(age >= 0 && age <= MAX_AGE_MS)) {
  process.stderr.write("❌ generate-pr-standards-block: no fresh green receipt (run `pnpm verify` first) — a non-green tree has no 100% block to generate\n");
  process.exit(1);
}

// Applicability probes — a standard the repo genuinely doesn't exercise is
// deliberately stamped NOT REQUIRED (never omitted). Everything else is 100%
// (backed by the green receipt).
const readJson = (p) => { try { return JSON.parse(fs.readFileSync(p, "utf8")); } catch { return null; } };
const pkg = readJson(path.join(process.cwd(), "package.json")) || {};
const deps = { ...pkg.dependencies, ...pkg.devDependencies };
const has = (d) => Object.keys(deps).some((k) => k === d || k.startsWith(`${d}/`) || k.startsWith(`@${d}/`));
let uiDiscipline = "full";
try {
  const auto = fs.readFileSync(path.join(process.cwd(), "..", "..", ".standards", "autonomy.yaml"), "utf8");
  uiDiscipline = (auto.match(/^ui_discipline:\s*(\S+)/m) || [])[1] || "full";
} catch { /* default full */ }

const NOT_REQUIRED = {
  GOOGLE_FIREBASE_STANDARDS: !has("firebase") && !has("firebase-admin") ? "no firebase dependency" : null,
  VERCEL_STANDARDS: !fs.existsSync(path.join(process.cwd(), "vercel.json")) && !fs.existsSync(path.join(process.cwd(), ".vercel")) ? "not a Vercel-deployed app" : null,
  PACKAGE_PROJECT_STANDARDS: !pkg.publishConfig && pkg.private !== false ? "not a published npm package" : null,
  AUTHORIZATION_STANDARDS: !has("drizzle-orm") && !has("pg") && !has("postgres") ? "no Postgres/Drizzle in this repo" : null,
  COMPONENT_CREATION: uiDiscipline === "none" ? "ui_discipline: none" : null,
  COMPOSITE_CREATION: uiDiscipline === "none" ? "ui_discipline: none" : null,
  PAGE_CREATION: uiDiscipline === "none" ? "ui_discipline: none" : null,
  SITE_BLUEPRINT: uiDiscipline === "none" ? "ui_discipline: none" : null,
  BROWSER_VALIDATION: uiDiscipline === "none" ? "ui_discipline: none" : null,
};

const lines = [
  "## Standards compliance",
  "",
  `100% standards met — ${receipt.gates}/${receipt.gates} gates green at ${receipt.ts}`,
  "",
  ...standards.map((s) => NOT_REQUIRED[s] ? `- ${s}: NOT REQUIRED` : `- ${s}: 100%`),
  "",
];
process.stdout.write(lines.join("\n"));
